SELECT COUNT(*) FROM users as u, comments as c, postLinks as pl, posts as p WHERE u.Id = p.OwnerUserId AND p.Id = pl.RelatedPostId AND p.Id = c.PostId AND u.CreationDate>='2011-02-08 18:11:37'::timestamp AND pl.LinkTypeId=1 AND pl.CreationDate>='2011-04-12 15:23:59'::timestamp AND p.Score=1 AND p.ViewCount>=0 AND p.FavoriteCount>=0;